import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"艮","description":"焦氏易林注 - 艮","frontmatter":{"title":"艮","description":"焦氏易林注 - 艮"},"headers":[],"relativePath":"zh/classics/jiaoyilin/052.md","filePath":"zh/classics/jiaoyilin/052.md"}'),l={name:"zh/classics/jiaoyilin/052.md"};function n(d,a,t,s,o,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="艮" tabindex="-1">艮 <a class="header-anchor" href="#艮" aria-label="Permalink to “艮”">​</a></h1><h3 id="艮-1" tabindex="-1">艮 <a class="header-anchor" href="#艮-1" aria-label="Permalink to “艮”">​</a></h3><h3 id="艮之乾" tabindex="-1">艮之乾 <a class="header-anchor" href="#艮之乾" aria-label="Permalink to “艮之乾”">​</a></h3><h3 id="林辞" tabindex="-1">林辞 <a class="header-anchor" href="#林辞" aria-label="Permalink to “林辞”">​</a></h3><p>憂驚已除，禍不為災，安全以來。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>艮中爻坎，坎為憂，中爻震，震為驚，今艮之乾，坎與震象皆不見，故曰憂驚已除，禍不為災。乾為福，故曰安全。</p><h3 id="艮之坤" tabindex="-1">艮之坤 <a class="header-anchor" href="#艮之坤" aria-label="Permalink to “艮之坤”">​</a></h3><h3 id="林辞-1" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-1" aria-label="Permalink to “林辞”">​</a></h3><p>穿匏挹水，篝鐵然火。勞疲力竭，饑渴為禍。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>艮為匏，今化坤，上爻拆，故曰穿匏。又艮卦坎為穿，坎水，艮手，故曰挹水。艮為篝，篝，籠也。為鐵、為火，夫穿匏挹水篝鐵然火，皆不能之事，故勞疲無功。坎為勞、為禍，坤虛，故飢。艮火，故渴。</p><h3 id="艮之屯" tabindex="-1">艮之屯 <a class="header-anchor" href="#艮之屯" aria-label="Permalink to “艮之屯”">​</a></h3><h3 id="林辞-2" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-2" aria-label="Permalink to “林辞”">​</a></h3><p>蹇牛折角，不能載粟。災害不避，年歲無谷。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>坤為牛，艮為角，上坎，故曰蹇牛折角。坤為載，震為粟、為谷，坤為年歲、為災害，故無谷也。</p><h3 id="艮之蒙" tabindex="-1">艮之蒙 <a class="header-anchor" href="#艮之蒙" aria-label="Permalink to “艮之蒙”">​</a></h3><h3 id="林辞-3" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-3" aria-label="Permalink to “林辞”">​</a></h3><p>邑將為墟，居之憂危。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>坤為邑，坎破，故為墟、為憂危。</p><h3 id="艮之需" tabindex="-1">艮之需 <a class="header-anchor" href="#艮之需" aria-label="Permalink to “艮之需”">​</a></h3><h3 id="林辞-4" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-4" aria-label="Permalink to “林辞”">​</a></h3><p>根刖樹殘，華葉落去。卒逢火焱，隨風僵僕。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>此仍用艮象。伏巽，下斷，故曰別、曰樹殘。伏兌為華，震為葉，巽隕，故曰華葉落去。艮為火，重艮，故曰焱。焱，音，火華也。班固《東都賦》焱焱炎炎。巽風，坎陷，故僕。</p><h3 id="艮之訟" tabindex="-1">艮之訟 <a class="header-anchor" href="#艮之訟" aria-label="Permalink to “艮之訟”">​</a></h3><h3 id="林辞-5" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-5" aria-label="Permalink to “林辞”">​</a></h3><p>元後貪欲，窮極民力。執政乖互，為夷所覆。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>乾為君，故曰元後。坎為心，故曰欲。為勞，故曰窮極民力。伏坤為政、為乖、為夷狄，坤喪，故曰覆。○互，元本作牙，汲古作劣，依宋本。與下覆協，牙互同。</p><h3 id="艮之師" tabindex="-1">艮之師 <a class="header-anchor" href="#艮之師" aria-label="Permalink to “艮之師”">​</a></h3><h3 id="林辞-6" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-6" aria-label="Permalink to “林辞”">​</a></h3><p>北山有棗，使叔壽考。東嶺多慄，宜行賈市。陸梁雌雉，所至利喜。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>此仍用艮象。艮為棗慄，下艮與坎連，故曰北山。上艮與震連，故曰東山。艮為叔、為壽，伏巽為賈市，離為雉。○慄，汲古訛粟，依宋元本。喜，宋元本作害，依汲古。</p><h3 id="艮之比" tabindex="-1">艮之比 <a class="header-anchor" href="#艮之比" aria-label="Permalink to “艮之比”">​</a></h3><h3 id="林辞-7" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-7" aria-label="Permalink to “林辞”">​</a></h3><p>高原峻山，陸土少泉。草木林麓，嘉禾所炎。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>艮為高原峻山，坤為陸土，坎為泉，坎下乘坤土，艮火，故曰少泉。坤為品物，故曰草木林麓、曰嘉禾。艮為火，故曰炎。○炎，汲古作災，依宋元本。</p><h3 id="艮之小畜" tabindex="-1">艮之小畜 <a class="header-anchor" href="#艮之小畜" aria-label="Permalink to “艮之小畜”">​</a></h3><h3 id="林辞-8" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-8" aria-label="Permalink to “林辞”">​</a></h3><p>辰次降婁，王駕巡狩。廣施德惠，國安無憂。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>通《豫》。艮居西北，降婁者戌次，故曰辰次降婁。震為王、為災狩、為德惠，坤為國，艮安，坤為憂，震出，故無憂。○狩，宋元本作時，非。第三句宋本作廣佑德惠，元本作廣佑施惠，依汲古。</p><h3 id="艮之履" tabindex="-1">艮之履 <a class="header-anchor" href="#艮之履" aria-label="Permalink to “艮之履”">​</a></h3><h3 id="林辞-9" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-9" aria-label="Permalink to “林辞”">​</a></h3><p>轠轠，歲暮偏弊。寵名損棄，君衰於位。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>通《謙》。震為車、為聲，故曰。，車聲也。而坤亦為車，故曰轠轠。轠，音雷，連屬不絕也。坎為暮，坤為歲，故曰歲暮。巽為弊，故曰偏弊。艮為名，坤喪，故曰損棄。震為君，坤敝，故衰於位。艮為位也。○損，汲古作復，轠作，茲依宋元本。</p><h3 id="艮之泰" tabindex="-1">艮之泰 <a class="header-anchor" href="#艮之泰" aria-label="Permalink to “艮之泰”">​</a></h3><h3 id="林辞-10" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-10" aria-label="Permalink to “林辞”">​</a></h3><p>放銜委轡，犇亂不制。法度無恆，君失其位。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>互兌為銜，伏巽為轡，震出，故曰放銜委轡、曰奔亂不制，坤為亂也。乾君在下，故曰失位。○犇，汲古作奔，字同。恆，汲古作常，均依宋元本。</p><h3 id="艮之否" tabindex="-1">艮之否 <a class="header-anchor" href="#艮之否" aria-label="Permalink to “艮之否”">​</a></h3><h3 id="林辞-11" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-11" aria-label="Permalink to “林辞”">​</a></h3><p>獨坐西垣，莫與笑言。秋風多哀，使我心悲。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>艮為坐、為垣，伏兌，故曰西垣。震為笑言，震伏，故莫與笑言。巽風，伏兌，故曰秋風。坤為心、為悲哀、為我。○坐，汲古作登，依宋元本。</p><h3 id="艮之同人" tabindex="-1">艮之同人 <a class="header-anchor" href="#艮之同人" aria-label="Permalink to “艮之同人”">​</a></h3><h3 id="林辞-12" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-12" aria-label="Permalink to “林辞”">​</a></h3><p>脛急股攣，不可出門。暮速群旅，必為身患。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>伏震為脛，巽為股，巽風，故曰急。巽為繩、為系，故曰攣。攣，音戀，手足田病也。乾為門，巽隕，故不可出門。坤為暮、為群、為身、為患。暮速群旅者，言使伴旅至暮戒備也。○群，宋元本作歸，依汲古。</p><h3 id="艮之大有" tabindex="-1">艮之大有 <a class="header-anchor" href="#艮之大有" aria-label="Permalink to “艮之大有”">​</a></h3><h3 id="林辞-13" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-13" aria-label="Permalink to “林辞”">​</a></h3><p>情偽難知，使我偏頗。小人在位，雖聖何咎。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>通《比》。坎為心，又為隱伏，故曰情偽難知。坤為我，坎為邪曲，故曰偏頗。坤為小人，艮為位，故曰小人在位。坎為聖、為咎。</p><h3 id="艮之謙" tabindex="-1">艮之謙 <a class="header-anchor" href="#艮之謙" aria-label="Permalink to “艮之謙”">​</a></h3><h3 id="林辞-14" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-14" aria-label="Permalink to “林辞”">​</a></h3><p>黍稷醇醴，敬奉山宗。神嗜飲食，甘雨嘉降。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>庶物蕃茂，時無災咎。詳《比》之《需》。汲古多獨蒙福祉四字，依宋元本。</p><h3 id="艮之豫" tabindex="-1">艮之豫 <a class="header-anchor" href="#艮之豫" aria-label="Permalink to “艮之豫”">​</a></h3><h3 id="林辞-15" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-15" aria-label="Permalink to “林辞”">​</a></h3><p>公子王孫，把彈攝丸。發輒有獲，室家饒足。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>詳《比》之《小畜》。</p><h3 id="艮之隨" tabindex="-1">艮之隨 <a class="header-anchor" href="#艮之隨" aria-label="Permalink to “艮之隨”">​</a></h3><h3 id="林辞-16" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-16" aria-label="Permalink to “林辞”">​</a></h3><p>陰升陽伏，舜失其室。慈母赤子，相喂不食。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>陰上陽下，故曰陰升陽伏。震為帝，故曰舜。艮為室，兌毀，故舜失其室。巽母，故慈。震子，艮納丙，故曰赤子。震為食，正覆震，故曰相喂。以飯哺人曰喂，艮止故不食。○慈母，汲古作元元，喂作餒，茲依宋元本。</p><h3 id="艮之蠱" tabindex="-1">艮之蠱 <a class="header-anchor" href="#艮之蠱" aria-label="Permalink to “艮之蠱”">​</a></h3><h3 id="林辞-17" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-17" aria-label="Permalink to “林辞”">​</a></h3><p>七竅龍身，造易八元。法天則地，順時施恩，利以長存。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>詳《謙》之《升》。</p><h3 id="艮之臨" tabindex="-1">艮之臨 <a class="header-anchor" href="#艮之臨" aria-label="Permalink to “艮之臨”">​</a></h3><h3 id="林辞-18" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-18" aria-label="Permalink to “林辞”">​</a></h3><p>逐狐東山，水遏我前。深不可涉，失利後便。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>詳《蒙》之《蠱》。</p><h3 id="艮之觀" tabindex="-1">艮之觀 <a class="header-anchor" href="#艮之觀" aria-label="Permalink to “艮之觀”">​</a></h3><h3 id="林辞-19" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-19" aria-label="Permalink to “林辞”">​</a></h3><p>銜命辱使，不堪其事。中墜落去，更為負載。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>巽為命，伏兌，故曰銜命。坤為事，巽為隕落，故曰中墜落去。艮為負，坤車，故曰載。</p><h3 id="艮之噬嗑" tabindex="-1">艮之噬嗑 <a class="header-anchor" href="#艮之噬嗑" aria-label="Permalink to “艮之噬嗑”">​</a></h3><h3 id="林辞-20" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-20" aria-label="Permalink to “林辞”">​</a></h3><p>溫仁君子，忠孝所在。入閨為儀，禍災不起。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>震為溫仁，艮為君子，坎為忠，伏巽為孝、為入，艮為閨，離為禮，故曰入閨為儀。離為禍災，震解，故曰禍災不起。○入閨，汲古作八閏，依宋元本。</p><h3 id="艮之賁" tabindex="-1">艮之賁 <a class="header-anchor" href="#艮之賁" aria-label="Permalink to “艮之賁”">​</a></h3><h3 id="林辞-21" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-21" aria-label="Permalink to “林辞”">​</a></h3><p>春多膏澤，夏潤優渥。稼穡成熟，畝獲百斛。師行失律，霸功不遂。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>震為春，離為夏，坎為膏澤、為優渥。震為稼穡，艮為成、為畝，震為斛、為百，故曰畝獲百斛。師行二句與上文不類，定為衍文。○成熟與斛韻，汲古作熟成，非，依宋元本。</p><h3 id="艮之剝" tabindex="-1">艮之剝 <a class="header-anchor" href="#艮之剝" aria-label="Permalink to “艮之剝”">​</a></h3><h3 id="林辞-22" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-22" aria-label="Permalink to “林辞”">​</a></h3><p>二女同室，心不聊食。首髪如蓬，憂常在中。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>艮為室，重坤，故曰二女。坤為心，兌為食，兌伏，故不食。艮為首，坤為憂，髪象蓬象疑用坤，否則用遇卦艮象，艮中爻互震為蓬、為髪，互坎為中。</p><h3 id="艮之復" tabindex="-1">艮之復 <a class="header-anchor" href="#艮之復" aria-label="Permalink to “艮之復”">​</a></h3><h3 id="林辞-23" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-23" aria-label="Permalink to “林辞”">​</a></h3><p>築闕石巔，立基泉源。病疾不安，老孤為鄰。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>此用《艮》象。艮為闕、為石，重艮，故曰築闕石巔。互坎為泉，震為基，在坎上，故曰立基泉源。坎為疾病、為孤，艮為壽，故為老。震為鄰也。○闕，宋元本作關，孤訛狐，均依汲古。基，宋元本作本，汲古作木，皆形訛字，依《漸》之《益》校。</p><h3 id="艮之無妄" tabindex="-1">艮之無妄 <a class="header-anchor" href="#艮之無妄" aria-label="Permalink to “艮之無妄”">​</a></h3><h3 id="林辞-24" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-24" aria-label="Permalink to “林辞”">​</a></h3><p>欲避凶門，反與禍鄰。顛覆不制，痛熏我心。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>乾為門，巽隕，故曰凶門。巽伏，故曰避。伏坤，故曰禍鄰。震為鄰也。巽隕，故曰顛覆。坤為心、為痛、為我，《艮九三》雲厲熏心，林所本也。</p><h3 id="艮之大畜" tabindex="-1">艮之大畜 <a class="header-anchor" href="#艮之大畜" aria-label="Permalink to “艮之大畜”">​</a></h3><h3 id="林辞-25" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-25" aria-label="Permalink to “林辞”">​</a></h3><p>踧行竊視，有所畏避。狸首伏藏，以夜為利。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>此用艮象。互震為行，艮為視，互坎為險，故曰踧行。踧，敬畏不安之貌也。互坎為盜，故曰竊視。坎為伏，故曰畏避。艮為狸、為首，互坎，故曰伏藏。坎為夜，言狸利夜動也。又狸首，逸詩篇名，《周禮春官》鐘師凡射王奏騶虞，諸侯奏狸首。按：此言樂節。狸，《周禮》、《禮記》皆作狸，《莊子》、《史記》皆作狸，《廣韻》狸，狸俗字。</p><h3 id="艮之頤" tabindex="-1">艮之頤 <a class="header-anchor" href="#艮之頤" aria-label="Permalink to “艮之頤”">​</a></h3><h3 id="林辞-26" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-26" aria-label="Permalink to “林辞”">​</a></h3><p>人面鬼口，長舌為斧。斫破瑚璉，殷商絕後。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>震為人，艮為面，坤為鬼，震為口，故曰人面鬼口。伏兌為舌、為斧，巽為長，故曰長舌為斧。艮手為斫，震為玉，故曰瑚璉。震為子，殷商子姓，而坤為殺、為死，故曰殷商絕後。震為後也。○斫，宋元本作劈，依汲古。人鬼，汲古作八九，九與鬼本通用，鬼侯作九侯是也，茲依宋元本。</p><h3 id="艮之大過" tabindex="-1">艮之大過 <a class="header-anchor" href="#艮之大過" aria-label="Permalink to “艮之大過”">​</a></h3><h3 id="林辞-27" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-27" aria-label="Permalink to “林辞”">​</a></h3><p>和氣相薄，膏澤津液，生我嘉谷。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>兌悅，故曰和。正反兌故曰相薄。兌水，故曰膏澤津液。巽為谷，乾為生。</p><h3 id="艮之坎" tabindex="-1">艮之坎 <a class="header-anchor" href="#艮之坎" aria-label="Permalink to “艮之坎”">​</a></h3><h3 id="林辞-28" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-28" aria-label="Permalink to “林辞”">​</a></h3><p>銷金●兵，雷車不行，民安其鄉。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>艮為金，艮火故銷金。艮為兵戈，艮止，故●兵。震為車、為雷，艮止坎陷，故不行。坎為民，艮為鄉、為安，故曰民安其鄉。○●，汲古作鑄，非，依宋元本。</p><h3 id="艮之離" tabindex="-1">艮之離 <a class="header-anchor" href="#艮之離" aria-label="Permalink to “艮之離”">​</a></h3><h3 id="林辞-29" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-29" aria-label="Permalink to “林辞”">​</a></h3><p>秦儀機言，解其國患。說燕下齊，作相以權。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>互兌為秦，離為禮，故曰儀。蘇秦、張儀也。中爻正反兌，故曰機言。伏艮為國，坎為患，震為解，故曰解其國患。兌為說，說燕指秦，下齊指儀。兌為燕，巽為齊、為權。按：秦儀說齊燕見《史記》。作相以權者，言秦六國相，儀為秦相魏，皆權詐之事。下，猶服也。○三四句各本皆作一說燕下，齊相以權，依王校。</p><h3 id="艮之咸" tabindex="-1">艮之咸 <a class="header-anchor" href="#艮之咸" aria-label="Permalink to “艮之咸”">​</a></h3><h3 id="林辞-30" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-30" aria-label="Permalink to “林辞”">​</a></h3><p>旦奭輔王，周德孔明。越裳獻雉，萬國咸康。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>通《損》。震為旦、為奭、為王、為周孔，坤為裳、為雉、為萬國，艮為安，故曰咸康。《史記》周召秉政，越裳氏獻白雉。○輔王，宋元本作王輔，非，王與明韻。</p><h3 id="艮之恒" tabindex="-1">艮之恒 <a class="header-anchor" href="#艮之恒" aria-label="Permalink to “艮之恒”">​</a></h3><h3 id="林辞-31" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-31" aria-label="Permalink to “林辞”">​</a></h3><p>弱足刖跟，不利出門。賈市無盈，折亡為患。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>震為足、為跟，兌折，故弱足。初震爻下斷，故曰刖跟。伏艮為門，是刖故不利出門。巽為賈市，兌毀折，故不利也。</p><h3 id="艮之遯" tabindex="-1">艮之遯 <a class="header-anchor" href="#艮之遯" aria-label="Permalink to “艮之遯”">​</a></h3><h3 id="林辞-32" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-32" aria-label="Permalink to “林辞”">​</a></h3><p>堅冰黃鳥，常哀悲愁。不見白粒，但睹藜蒿。數驚鷙鳥，為我心憂。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>詳《乾》之《噬嗑》。常，宋元本訛帝，依汲古。藜元訛蔾，依宋本。</p><h3 id="艮之大壯" tabindex="-1">艮之大壯 <a class="header-anchor" href="#艮之大壯" aria-label="Permalink to “艮之大壯”">​</a></h3><h3 id="林辞-33" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-33" aria-label="Permalink to “林辞”">​</a></h3><p>魂微惙惙，屬纊聽絕。豁然大通，復更生活。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>詳《明夷》之《恆》。</p><h3 id="艮之晉" tabindex="-1">艮之晉 <a class="header-anchor" href="#艮之晉" aria-label="Permalink to “艮之晉”">​</a></h3><h3 id="林辞-34" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-34" aria-label="Permalink to “林辞”">​</a></h3><p>陰生麞鹿，鼠舞鬼哭，靈龜陸處。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>坤為陰，艮為麞鹿、為鼠，坤為鬼，震為笑歌，震反為艮則哭泣矣。《中孚六三》即如此取象也。離為龜，坤艮皆為陸，故曰陸處。○汲古下多&quot;釜甑草土，人知敗國，桀亂無緒&quot;三句，元本同，惟釜作雨，土作坐，人作仁，依宋本，然似有三句而意始足。坤為釜甑、為草土、為國，坎為敗，離為惡人、為亂，故曰桀紂無緒。</p><h3 id="艮之明夷" tabindex="-1">艮之明夷 <a class="header-anchor" href="#艮之明夷" aria-label="Permalink to “艮之明夷”">​</a></h3><h3 id="林辞-35" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-35" aria-label="Permalink to “林辞”">​</a></h3><p>諸石攻玉，無不穿。龍體具舉，魯班為輔。麟鳳成形，德象君子。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>詳《姤》之《大過》。諸石即監諸。具，宋本、汲古作吾，依元本。○大過伏頤，此則用艮，艮三至上亦頤，故語同。</p><h3 id="艮之家人" tabindex="-1">艮之家人 <a class="header-anchor" href="#艮之家人" aria-label="Permalink to “艮之家人”">​</a></h3><h3 id="林辞-36" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-36" aria-label="Permalink to “林辞”">​</a></h3><p>山作天時，陸為海口，民不安處。此用艮象。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>艮為天、為時，故曰山作天時。艮為陸，中爻坎為海，震為口，坎為民，坎陷，故不安。天時，疑皆訛。</p><h3 id="艮之睽" tabindex="-1">艮之睽 <a class="header-anchor" href="#艮之睽" aria-label="Permalink to “艮之睽”">​</a></h3><h3 id="林辞-37" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-37" aria-label="Permalink to “林辞”">​</a></h3><p>東風啟戶，隱伏歡喜。氓庶蒙恩，復得我子。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>此仍用艮象。互震為東，伏巽，故曰東風啟戶。坎為隱伏、為氓庶，震為歡喜、為子。</p><h3 id="艮之蹇" tabindex="-1">艮之蹇 <a class="header-anchor" href="#艮之蹇" aria-label="Permalink to “艮之蹇”">​</a></h3><h3 id="林辞-38" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-38" aria-label="Permalink to “林辞”">​</a></h3><p>華燈百枝，消暗衰微。精光欲盡，奄如灰糜。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>詳《隨》之《大有》。消，宋元本作稍，汲古作植，依《隨》之《大有》校。糜，爛也。宋本作靡，依汲古。奄，汲古作命，亦通，茲依宋元本。</p><h3 id="艮之解" tabindex="-1">艮之解 <a class="header-anchor" href="#艮之解" aria-label="Permalink to “艮之解”">​</a></h3><h3 id="林辞-39" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-39" aria-label="Permalink to “林辞”">​</a></h3><p>三十無室，寄宿桑中。上宮長女，不得樂同，使我失期。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>《衛風》期我乎桑中，要我乎上宮，淫奔詩也，此仍取艮象。互震數三，伏兌數十，坎為室，坎伏，故曰三十無室。坎為宿，震為桑，故曰寄宿桑中。艮為上、為宮，巽為長女，巽伏，故曰不得樂同。坎為失，艮為期。○樂，宋元本作來，依汲古。汲古無末句，依宋元本補。又宿字汲古作伯，形不全，依宋元本。</p><h3 id="艮之損" tabindex="-1">艮之損 <a class="header-anchor" href="#艮之損" aria-label="Permalink to “艮之損”">​</a></h3><h3 id="林辞-40" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-40" aria-label="Permalink to “林辞”">​</a></h3><p>卵與石鬬，糜碎無疑。動而有悔，出不得時。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>震為卵，艮為石，震艮相對，故曰鬬。兌毀，故曰糜碎。震為動，坤為悔，艮為時。○糜，宋元本作麋，依汲古。</p><h3 id="艮之益" tabindex="-1">艮之益 <a class="header-anchor" href="#艮之益" aria-label="Permalink to “艮之益”">​</a></h3><h3 id="林辞-41" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-41" aria-label="Permalink to “林辞”">​</a></h3><p>秦兵爭強，失其貞良，敗於淆鄉。伏兌為秦，坤為兵，正反震故曰爭強。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>艮為貞良，坤喪，故曰失。艮山，故曰淆鄉。《左傳》秦穆公違蹇叔，使孟明伐鄭，敗於淆。</p><h3 id="艮之夬" tabindex="-1">艮之夬 <a class="header-anchor" href="#艮之夬" aria-label="Permalink to “艮之夬”">​</a></h3><h3 id="林辞-42" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-42" aria-label="Permalink to “林辞”">​</a></h3><p>豦除善疑，難為攻醫。驥窮鹽車，困於銜棰。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>豦除，即篨。籧同。《爾雅》籧篨口柔。《詩邶風》《毛傳》雲：籧篨不能俯者。郭雲：口柔之人視人顏色常亦不伏，因以為名。按：疏：口柔之人，必仰面察人顏色而為辭，故曰善疑。豦除為生成之病，故不能攻治也。此仍用艮象。艮為豦除，互坎為疑，三至上正反艮，故曰攻醫。坎陷，故難。互震為車、為馬，兌為滷，故曰鹽車，故曰銜。坎為困窮，故曰驥窮鹽車，困於銜棰。棰，馬策也。艮為小木，故曰棰。○豦，宋本、汲古訛虐，元本訛虎，然由次句視之，其為豦無疑也。疑，宋元本作猛，亦後人從虎虐二字妄改，獨汲古尚存其真，益證豦字之確切。棰，汲古作御，依元本。按：《說文》豦，司馬相如說封豕之屬，封豕，亦不能俯。《太玄》閑首作遽除，皆不從竹，疑古文詩即如此，故易林太玄皆不從竹。從竹，後人所加。易女承筐，鄭作匡，謂從竹者誤，茲殆與同。</p><h3 id="艮之姤" tabindex="-1">艮之姤 <a class="header-anchor" href="#艮之姤" aria-label="Permalink to “艮之姤”">​</a></h3><h3 id="林辞-43" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-43" aria-label="Permalink to “林辞”">​</a></h3><p>操笱搏狸，荷弓射魚。非其器用，自令心勞。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>此仍用艮象。艮為狸，艮手為操、為搏，伏離為笱，故曰操笱搏狸。艮為荷，坎為弓，震為射，伏巽為魚，震為器。坎為心、為勞。笱所以取魚，弓矢所以射狸，今施非物，故無功也。</p><h3 id="艮之萃" tabindex="-1">艮之萃 <a class="header-anchor" href="#艮之萃" aria-label="Permalink to “艮之萃”">​</a></h3><h3 id="林辞-44" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-44" aria-label="Permalink to “林辞”">​</a></h3><p>葵邱之盟，晉獻會行。見太宰辭，復為還輿。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>兌為華，艮山，故曰葵丘。兌為口，為巫，故曰盟。伏震為晉、為行，艮為官，故曰太宰。坤為輿，巽退，故曰還輿。按：《左傳僖九年》會於葵丘，王使宰孔賜齊侯胙，既盟，宰孔先歸，遇晉侯，曰：可無會也，齊將亂，晉侯乃還。</p><h3 id="艮之升" tabindex="-1">艮之升 <a class="header-anchor" href="#艮之升" aria-label="Permalink to “艮之升”">​</a></h3><h3 id="林辞-45" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-45" aria-label="Permalink to “林辞”">​</a></h3><p>臏詐龐子，夷竃書木。伏兵卒發，矢至如雨。魏師驚亂，將獲為虜，涓死樹下。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>刖足曰臏。巽下斷，故曰臏。正反兌口，故曰詐。震為子，坤亂，故曰龐子。坤為夷、為釜，故曰夷竃。夷，平也。震為木，坤文，故曰書木。坤為兵，巽為伏，震出，故曰伏兵卒發。初四互坎，坎為矢、為雨，震為魏、為驚，坤為師、為亂，故曰魏師驚亂。震為主、為將，坤為死喪，巽為樹。《史記孫臏傳》臏率齊兵與魏龐涓戰，日減竃，佯退兵，至馬陵道，設伏，並斫樹，使白大書曰：龐涓死此樹下。涓追至，鑽火視書，忽萬弩齊發，果被射死，公子卬被虜。○書木，宋元本作盡毀，伏兵作兵伏，均非，依汲古。末句依宋元本增，汲古無。</p><h3 id="艮之困" tabindex="-1">艮之困 <a class="header-anchor" href="#艮之困" aria-label="Permalink to “艮之困”">​</a></h3><h3 id="林辞-46" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-46" aria-label="Permalink to “林辞”">​</a></h3><p>南行出城，世得大福。王姬歸齊，賴其所欲。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>伏《賁》。震為南、為行，艮為城、為世，震為福、為王、為姬、為歸，巽為齊，《左傳莊二年》王姬歸齊魯為主。○大，元本作天，從汲古。</p><h3 id="艮之井" tabindex="-1">艮之井 <a class="header-anchor" href="#艮之井" aria-label="Permalink to “艮之井”">​</a></h3><h3 id="林辞-47" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-47" aria-label="Permalink to “林辞”">​</a></h3><p>冬採薇籣，地凍堅難。利走室北，暮無所得。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>巽為臭、為草莽，故曰薇蘭。坎為冬、為冰，故曰地凍。伏艮為堅，故曰堅難。坎為室、為北，巽為利，伏震為走，故曰利走室北。坎為暮，離虛，故無得。薇，宋元本作微，依汲古。</p><h3 id="艮之革" tabindex="-1">艮之革 <a class="header-anchor" href="#艮之革" aria-label="Permalink to “艮之革”">​</a></h3><h3 id="林辞-48" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-48" aria-label="Permalink to “林辞”">​</a></h3><p>王喬無病，狗頭不痛。亡屐失履，乏我送從。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>革伏《蒙》，艮為壽，故為仙人，王子喬，古仙人也。艮為狗、為頭，坎為病痛，艮在上出險，故不病痛。互震為屐履，坤為亡失、為乏。</p><h3 id="艮之鼎" tabindex="-1">艮之鼎 <a class="header-anchor" href="#艮之鼎" aria-label="Permalink to “艮之鼎”">​</a></h3><h3 id="林辞-49" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-49" aria-label="Permalink to “林辞”">​</a></h3><p>宛馬疾步，盲師坐御。目不見路，中宵不到。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>通《屯》。震為馬、為步，坎為疾，故曰疾步。屯初至五大離，故曰盲。坤為師，艮為坐、為御，故盲師坐御。震為大塗，坤坎皆為黑，故目不見路。坤為夜，坎為中，艮止，故中宵不到。○不，汲古作弗，非，依元本。</p><h3 id="艮之震" tabindex="-1">艮之震 <a class="header-anchor" href="#艮之震" aria-label="Permalink to “艮之震”">​</a></h3><h3 id="林辞-50" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-50" aria-label="Permalink to “林辞”">​</a></h3><p>求利難國，亡去我北。憂歸其城，反為吾賊。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>中爻艮為求、為國，坎為難，伏巽為利，故曰求利難國。坎為北、為憂，艮為城，震為反，故曰歸城。坎為盜賊。○吾賊，汲古作我賊，依宋元本。</p><h3 id="艮之艮" tabindex="-1">艮之艮 <a class="header-anchor" href="#艮之艮" aria-label="Permalink to “艮之艮”">​</a></h3><h3 id="林辞-51" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-51" aria-label="Permalink to “林辞”">​</a></h3><p>君孤獨處，單弱無輔，名曰困苦。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>互震為君，坎為孤，艮一陽在上，故為鰥、為獨、為單弱。坎為困苦。○汲古下有&quot;輔心涌泉，碌碌如山&quot;八字，明系衍文，依宋元本刪。</p><h3 id="艮之漸" tabindex="-1">艮之漸 <a class="header-anchor" href="#艮之漸" aria-label="Permalink to “艮之漸”">​</a></h3><h3 id="林辞-52" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-52" aria-label="Permalink to “林辞”">​</a></h3><p>比目四翼，安我邦國。上下無患，為吾喜福。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>通《歸妹》。互離，兌卦數二，故曰比目。震為翼，卦數四，故曰四翼。本卦艮為邦國，艮安，故曰安我邦國。艮山，故曰上。兌澤，故曰下。坎為患，震出，故曰無患。震為喜福，艮為吾。○吾喜，汲古作我嘉，依宋元本。</p><h3 id="艮之歸妹" tabindex="-1">艮之歸妹 <a class="header-anchor" href="#艮之歸妹" aria-label="Permalink to “艮之歸妹”">​</a></h3><h3 id="林辞-53" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-53" aria-label="Permalink to “林辞”">​</a></h3><p>八材既登，以成股肱。尨降庭堅，國無災凶。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>股肱，汲古作嘉功，依宋元本。伏巽為肘，艮為臂、為肱，震為鳴、為毛羽，故曰尨。尨，多毛犬也。伏艮為庭、為堅、為國，互坎為災凶，震解，故無。八材象或以震居東方。</p><h3 id="艮之豐" tabindex="-1">艮之豐 <a class="header-anchor" href="#艮之豐" aria-label="Permalink to “艮之豐”">​</a></h3><h3 id="林辞-54" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-54" aria-label="Permalink to “林辞”">​</a></h3><p>消弊穿空，家莫為宗。奴婢逃走，子西父東，為射作凶。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>巽隕落，故曰消弊。伏坎為穿，離虛，故曰空。伏艮為家，震為主、為宗，風散，故莫與為宗。艮為奴婢，艮伏，故曰逃走。震為子，兌西，故曰子西。震為父，故曰父東。伏艮為身，巽隕，故凶也。○消，宋元、汲古皆作稍，依局本。</p><h3 id="艮之旅" tabindex="-1">艮之旅 <a class="header-anchor" href="#艮之旅" aria-label="Permalink to “艮之旅”">​</a></h3><h3 id="林辞-55" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-55" aria-label="Permalink to “林辞”">​</a></h3><p>鳥舞國城，邑懼卒驚。仁德不修，為下所傾。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>艮為鳥、為舞、為國城、為邑，伏坎為懼。震為驚、為仁德，震伏，故曰仁德不修。兌為下，兌毀，故曰傾。</p><h3 id="艮之巽" tabindex="-1">艮之巽 <a class="header-anchor" href="#艮之巽" aria-label="Permalink to “艮之巽”">​</a></h3><h3 id="林辞-56" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-56" aria-label="Permalink to “林辞”">​</a></h3><p>五穀不熟，民苦困急。駕之南國，嘉樂有得。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>巽為谷，卦數五，故曰五穀。巽隕落，故不熟。伏坎為民、為困急。伏震為南，艮為國。○五，宋元本訛三。駕，元本作亟，均依汲古。三四言巽究為震，即安樂也。</p><h3 id="艮之兌" tabindex="-1">艮之兌 <a class="header-anchor" href="#艮之兌" aria-label="Permalink to “艮之兌”">​</a></h3><h3 id="林辞-57" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-57" aria-label="Permalink to “林辞”">​</a></h3><p>黃裳建元，福德在身。祿佑洋溢，封為齊君，富貴多孫。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>遇卦艮。互震為裳、為黃、為元、為福德祿佑。艮為身，互坎，故曰洋溢。震為君，本卦互巽，故曰齊君。艮為貴、為孫。○宋元本、汲古多賈市無門四字，在第五句，此於上下句義絕不屬，斷為衍文，刪去而存其語以俟校此書者。《坤六五》黃裳元吉，五君位，故曰建元。</p><h3 id="艮之渙" tabindex="-1">艮之渙 <a class="header-anchor" href="#艮之渙" aria-label="Permalink to “艮之渙”">​</a></h3><h3 id="林辞-58" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-58" aria-label="Permalink to “林辞”">​</a></h3><p>齊東郭盧，嫁於洛都。駿良美好，利得過倍。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>詳《坤》之《坎》。嫁，汲古作嬪，過作萬，盧作廬，均依宋元本。駿良，宋元作驪婦，依汲古。嫁，往也。</p><h3 id="艮之節" tabindex="-1">艮之節 <a class="header-anchor" href="#艮之節" aria-label="Permalink to “艮之節”">​</a></h3><h3 id="林辞-59" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-59" aria-label="Permalink to “林辞”">​</a></h3><p>安床厚縟，不得久宿。棄我嘉宴，困於南國。投杼之憂，不成禍災。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>艮為床，伏巽為縟，坎為宿，兌毀折，坎險，故不得久宿。兌食，震嘉，故曰嘉宴。坎為困，震南震國，故曰困於南國。坎為機杼、為憂、為禍災。《戰國策》有人與曾參同姓名殺人，人告其母，不信，三告，母乃投杼而走。</p><h3 id="艮之中孚" tabindex="-1">艮之中孚 <a class="header-anchor" href="#艮之中孚" aria-label="Permalink to “艮之中孚”">​</a></h3><h3 id="林辞-60" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-60" aria-label="Permalink to “林辞”">​</a></h3><p>內崩身傷，中亂無常。雖有美粟，不我得食。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>卦中虛，故曰內崩。艮為身，兌為傷，巽為粟，震為嘉，故曰美粟。兌為食，上卦兌覆，故不得食。○末句汲古作不得其食，依宋元本。</p><h3 id="艮之小過" tabindex="-1">艮之小過 <a class="header-anchor" href="#艮之小過" aria-label="Permalink to “艮之小過”">​</a></h3><h3 id="林辞-61" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-61" aria-label="Permalink to “林辞”">​</a></h3><p>出門逢患，與禍為怨。更相擊刺，傷我手端。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>此仍用艮象。艮為門，震出，中爻坎為患、為禍、為怨，艮為擊刺，三至上正覆艮相對，故曰更相擊刺。艮為手，坎為傷。</p><h3 id="艮之既濟" tabindex="-1">艮之既濟 <a class="header-anchor" href="#艮之既濟" aria-label="Permalink to “艮之既濟”">​</a></h3><h3 id="林辞-62" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-62" aria-label="Permalink to “林辞”">​</a></h3><p>出入節時，南北無憂。行者函至，在外歸來。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>此仍用艮象。震出，伏巽為入，艮為時，故曰出入節時。震為南，坎為北、為憂。震為行、為歸，艮為函，三至上震起艮止，故曰在外歸來。○函，汲古作即，依元本。</p><h3 id="艮之未濟" tabindex="-1">艮之未濟 <a class="header-anchor" href="#艮之未濟" aria-label="Permalink to “艮之未濟”">​</a></h3><h3 id="林辞-63" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-63" aria-label="Permalink to “林辞”">​</a></h3><p>公孫駕驪，載游東濟。延陵說產，遺季紵衣。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>此仍用艮象。震為公，艮為孫，震馬，故曰駕驪。震為游、為東，伏巽為齊，故曰東齊。艮為山、為季子，故曰延陵。吳延陵季子也。震為生、為樂，故曰悅產。產，鄭子產也。震為衣、為草莽，故曰紵衣。《左傳》吳季札至鄭，見子產如舊相識，與之縞帶，子產獻紵衣。○驪。汲古作車。依宋元本。</p>',322)])])}const f=e(l,[["render",n]]);export{p as __pageData,f as default};
